def mapper(line):
    for w in line.split():
        yield (w.lower(), 1)

docs = ["Hello world hello", "world of BigData", "hello bigdata world"]
kv = []
for line in docs:
    for k, v in mapper(line):
        kv.append((k, v))
for k, v in kv:
    print(f"{k}	{v}")
print(f"--total kv pairs: {len(kv)}")
